args.sparql:
SELECT DISTINCT ?director ?directorLabel ?birthPlace ?birthPlaceLabel WHERE {
  dbr:Timerider:_The_Adventure_of_Lyle_Swann (dbo:director|dbp:director) ?director .
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER(lang(?directorLabel) = 'en') }
  OPTIONAL { ?director dbo:birthPlace ?birthPlace . }
  OPTIONAL { ?director dbp:birthPlace ?birthPlace . }
  OPTIONAL { ?birthPlace rdfs:label ?birthPlaceLabel FILTER(lang(?birthPlaceLabel) = 'en') }
} LIMIT 50

SELECT DISTINCT ?birthPlace ?birthPlaceLabel ?type ?typeLabel WHERE {
  dbr:Timerider:_The_Adventure_of_Lyle_Swann (dbo:director|dbp:director) ?director .
  VALUES (?director) { (dbr:William_Dear) }
  { ?director dbo:birthPlace ?birthPlace . } UNION { ?director dbp:birthPlace ?birthPlace . }
  OPTIONAL { ?birthPlace rdf:type ?type . }
  OPTIONAL { ?birthPlace rdfs:label ?birthPlaceLabel FILTER(lang(?birthPlaceLabel)='en') }
  OPTIONAL { ?type rdfs:label ?typeLabel FILTER(lang(?typeLabel)='en') }
} LIMIT 100

SELECT DISTINCT ?director ?directorLabel ?birthPlace ?birthPlaceLabel WHERE {
  dbr:Timerider:_The_Adventure_of_Lyle_Swann (dbo:director|dbp:director) ?director .
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER(lang(?directorLabel) = 'en') }

  { ?director dbo:birthPlace ?birthPlace } UNION { ?director dbp:birthPlace ?birthPlace }

  # prefer birth places that are city/settlement/populated place
  ?birthPlace rdf:type ?btype .
  FILTER(?btype IN (dbo:City, dbo:Settlement, dbo:PopulatedPlace, dbo:Place))

  OPTIONAL { ?birthPlace rdfs:label ?birthPlaceLabel FILTER(lang(?birthPlaceLabel) = 'en') }
}
LIMIT 50

SELECT ?place ?label ?type ?typeLabel WHERE {
  VALUES ?place { dbr:Toronto dbr:Ontario }
  OPTIONAL { ?place rdfs:label ?label FILTER(lang(?label)='en') }
  ?place rdf:type ?type .
  OPTIONAL { ?type rdfs:label ?typeLabel FILTER(lang(?typeLabel)='en') }
} ORDER BY ?place LIMIT 200

SELECT DISTINCT ?director ?directorLabel ?birthPlace ?birthPlaceLabel WHERE {
  dbr:Timerider:_The_Adventure_of_Lyle_Swann (dbo:director|dbp:director) ?director .
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER(lang(?directorLabel) = 'en') }
  OPTIONAL { ?director dbo:birthPlace ?birthPlace . }
  OPTIONAL { ?director dbp:birthPlace ?birthPlace . }
  OPTIONAL { ?birthPlace rdfs:label ?birthPlaceLabel FILTER(lang(?birthPlaceLabel) = 'en') }
} LIMIT 50

