PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
SELECT DISTINCT ?director ?directorLabel ?birthPlace ?birthPlaceLabel WHERE {
  dbr:Timerider:_The_Adventure_of_Lyle_Swann(dbo:director | dbp:director) ?director .
  OPTIONAL {
    ?director rdfs:label ?directorLabel
    FILTER(lang(?directorLabel) = 'en')
  }
  OPTIONAL {
    ?director dbo:birthPlace ?birthPlace .
  }
  OPTIONAL {
    ?director dbp:birthPlace ?birthPlace .
  }
  OPTIONAL {
    ?birthPlace rdfs:label ?birthPlaceLabel
    FILTER(lang(?birthPlaceLabel) = 'en')
  }
}
LIMIT 50

